const abs=p=>p ? base+p : 'Not assigned — HOLD';
function add(keyword,p,decision,subject,grade,course,reason,priority='P2',competitor='oxSubjects',support='',extra={}) {
  const existing=extra.existing || (decision===N ? '/en' : p);
  const current=pages.get(existing);
  const row={id:`K${String(rows.length+1).padStart(3,'0')}`,keyword,searchIntent:extra.intent||'Commercial — select tutoring support',funnel:extra.funnel||'MOFU → BOFU',subject,grade,course:course||'Not course-specific',existingUrl:existing?abs(existing):'No adequate existing page',currentTitle:extra.title||current?.title||'Not crawled / no existing page',targetUrl:decision===H?'Not assigned — HOLD':abs(p),decision,reason,primaryKeyword:extra.primary||keyword,supportingKeywords:support||'No additional variants selected',cannibalizationRisk:extra.risk||'Medium — keep the subject hub broad and this page limited to its specific intent.',competitorExample:competitor?sources[competitor]:null,competitorScope:extra.competitorScope||'Related service/architecture example; not evidence of rank or search volume.',priority,volume:'DATA REQUIRED',keywordDifficulty:'DATA REQUIRED',positioning:extra.positioning||reason};
  if(decision!==H&&!owner.has(p))owner.set(p,{primary:row.primaryKeyword,positioning:row.positioning,priority});
  rows.push(row);
  return row;
}

