const h=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function inline(s){return h(s).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function mdHTML(md){const lines=md.split('\n');let output='',inTable=false,inList=false;for(const line of lines){if(line.startsWith('| ')){if(!inTable){output+='<div class="table-wrap"><table>';inTable=true;}if(/^\|(?: --- \|)+$/.test(line))continue;const cells=line.slice(2,-2).split(/(?<!\\) \| /).map(c=>c.replaceAll('\\|','|'));output+='<tr>'+cells.map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>';continue;}if(inTable){output+='</table></div>';inTable=false;}const heading=line.match(/^(#{1,3}) (.*)/);if(heading){const n=heading[1].length;output+=`<h${n}>${inline(heading[2])}</h${n}>`;continue;}if(line.trim())output+='<p>'+inline(line)+'</p>';}if(inTable)output+='</table></div>';return output;}
