const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Success Path Mentors — Master SEO Keyword-to-URL Map</title><style>body{font:16px/1.55 system-ui,sans-serif;margin:0;background:#f3f5f7;color:#172b3a}main{max-width:1440px;margin:auto;padding:32px}h1{font-size:34px;line-height:1.15;color:#205375}h2{margin-top:48px;color:#205375;border-bottom:2px solid #d5a021;padding-bottom:10px}h3{margin-top:28px}a{color:#155c86;overflow-wrap:anywhere}p{max-width:1100px}.table-wrap{overflow:auto;background:white;border:1px solid #ced7df;border-radius:8px;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid #dce3e8;border-right:1px solid #e5e9ee;text-align:left;vertical-align:top;padding:12px;min-width:120px;max-width:420px;overflow-wrap:anywhere}tr:first-child td,th{background:#205375;color:white;font-weight:700}tr:first-child td a,th a{color:white}tbody tr:nth-child(even){background:#f7f9fb}.matrix{max-height:720px}.matrix table{width:5300px}.matrix th{position:sticky;top:0;z-index:1}.matrix tbody tr:first-child td{background:inherit;color:inherit;font-weight:400}.matrix tbody tr:first-child td a{color:#155c86}.matrix td:nth-child(1){min-width:40px}.matrix td:nth-child(2){min-width:240px}.matrix td:nth-child(12){min-width:350px}.filter{display:flex;flex-wrap:wrap;gap:16px;align-items:end;background:#e4edf3;padding:20px;border-radius:8px}label{display:grid;gap:6px;font-weight:600}input,select{font:inherit;padding:9px;border:1px solid #9bacb8;border-radius:4px}input{width:320px}code{background:#e6ebef;padding:2px 4px}@media print{body{background:white}main{padding:0}.filter{display:none}.table-wrap{overflow:visible;max-height:none}.matrix table{width:100%;font-size:6px}td,th{padding:3px;min-width:0!important}h2{break-after:avoid}}</style></head><body><main>'+mdHTML(intro)+filter+htmlTable+mdHTML(summaryA+summaryB+summaryC+summaryD+inventory+ending)+'</main><script>const q=document.querySelector("#query"),d=document.querySelector("#decision"),p=document.querySelector("#priority"),rs=[...document.querySelectorAll("#matrix tbody tr")];function filter(){let n=0;for(const r of rs){const show=(!q.value||r.textContent.toLowerCase().includes(q.value.toLowerCase()))&&(!d.value||r.dataset.decision===d.value)&&(!p.value||r.dataset.priority===p.value);r.hidden=!show;if(show)n++}document.querySelector("#visible").textContent=n+" of "+rs.length+" clusters"}for(const e of [q,d,p])e.addEventListener("input",filter);filter();</script></body></html>';
